  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Øygardstøl – Orlí hnízdo', 'Vyhlídka a kavárna přezdívaná Ørneredet (Orlí hnízdo) na hraně tisícimetrového srázu nad Lysebotnem. Odsud startuje pěší túra na Kjerag a z terasy je vidět celá kaskáda serpentin Lysevegenu pod vámi. Povinná zastávka na fotku a kafe, než se pustíte dolů.', 59.0339, 6.6496, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%98ygardst%C3%B8l.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%98ygardst%C3%B8l.jpg"}'::text[], 0),
    (v_route, 'Kjeragbolten', 'Legendární balvan vklíněný ve skalní puklině tisíc metrů nad hladinou Lysefjordu — jedno z nejslavnějších fotomíst Norska. Z parkoviště Øygardstøl na něj vede náročná túra tam a zpět asi 10 km (počítejte 5–6 hodin), takže se hodí spíš jako celodenní přídavek k vyjížďce. I bez túry stojí masiv Kjeragu za pohled z vyhlídky.', 59.0336, 6.5931, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kjeragbolten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kjeragbolten.jpg"}'::text[], 1),
    (v_route, 'Lysevegen – 27 serpentin', 'Klenot celé trasy: 27 vlásenek nad sebou, které klesají z 932 metrů prakticky na úroveň moře. Součástí sjezdu je i 1,1 km dlouhý tunel vytesaný do skály, který se uvnitř stáčí o 340 stupňů. Jeďte na jedničku až dvojku, hlídejte štěrk na vnitřních obloucích a užívejte si výhledy — něco podobného v Evropě moc nenajdete.', 59.0480, 6.6640, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lysevegen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lysevegen.jpg"}'::text[], 2),
    (v_route, 'Lysebotn', 'Maličká osada na samém konci Lysefjordu, sevřená kolmými skalními stěnami — v létě mekka motorkářů a basejumperů, kteří skáčou z okolních stěn. Je tu kemp, kiosek a přístaviště trajektu. Ideální místo, kde nechat doznít adrenalin ze sjezdu.', 59.0553, 6.6432, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lysebotn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lysebotn.jpg"}'::text[], 3),
    (v_route, 'Lysefjord – plavba trajektem', 'Z Lysebotnu vyplouvá v sezóně trajekt, který proveze vás i motorku celým 42 km dlouhým fjordem pod stěnou Kjeragu a pod skalní plošinou Preikestolen. Plavba trvá kolem dvou hodin a je to nejpohodlnější (a nejkrásnější) cesta zpět k civilizaci směrem na Stavanger. V hlavní sezóně si místo pro motorku rezervujte předem.', 59.0300, 6.3500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lysefjorden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lysefjorden.jpg"}'::text[], 4);
  insert into public.routes
