  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Stryn', 'Živé městečko mezi fjordem Nordfjord a horami, přirozená základna pro celý region. Doplňte tu palivo i zásoby — na horské části trasy už žádná pumpa není. V okolí najdete řadu kaváren a pekáren na rozjezdovou kávu.', 61.9046, 6.7114, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stryn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stryn.jpg"}'::text[], 0),
    (v_route, 'Loen a jezero Lovatnet', 'Krátká odbočka z hlavního tahu k jednomu z nejfotogeničtějších jezer Norska — ledovcová voda Lovatnetu má neuvěřitelnou tyrkysovou barvu. Podél břehu vede úzká klidná silnička ideální na pomalou vyhlídkovou jízdu. Z Loen jezdí i lanovka Loen Skylift na vrchol Hoven s výhledem na celý fjord.', 61.8380, 6.8480, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lovatnet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lovatnet.jpg"}'::text[], 1),
    (v_route, 'Videfossen', 'Mohutný vodopád přezdívaný Buldrefossen (Hřmící vodopád), který padá přímo u serpentin stoupání na Strynefjellet. Vodní tříšť často doletí až na silnici, tak pozor na mokrý asfalt v zatáčkách. Hned u cesty je vyhlídkové odpočívadlo na fotku.', 61.9640, 7.2260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Videfossen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Videfossen.jpg"}'::text[], 2),
    (v_route, 'Videseter', 'Horský hotel z 19. století vysoko nad údolím Hjelledalen, u kterého začíná historická část staré cesty. Z terasy je jeden z nejlepších výhledů celé trasy — hluboko dolů na údolí a serpentiny, kterými jste právě vyjeli. Příjemná zastávka na kávu a vafle.', 61.9727, 7.2320, 'https://commons.wikimedia.org/wiki/Special:FilePath/Videseter.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Videseter.jpg"}'::text[], 3),
    (v_route, 'Gamle Strynefjellsvegen', 'Samotná historická cesta z roku 1894: úzký pás mezi kamennými patníky, ledovcovými jezery a sněhovými poli, která tu leží celé léto. Jede se pomalu, ale právě proto si vychutnáte atmosféru staré horské silnice, po které kdysi jezdily kočáry. Jeden z nejkrásnějších úseků, jaké v Norsku na motorce potkáte.', 61.9950, 7.3900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Strynefjellsvegen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Strynefjellsvegen.jpg"}'::text[], 4),
    (v_route, 'Grotli', 'Osada s historickým vysokohorským hotelem Grotli Høyfjellshotell z roku 1874 na křižovatce horských cest. Cílová zastávka na oběd nebo nocleh; odsud se dá pokračovat na východ do Lomu, nebo se vrátit novou silnicí Rv15 tunely zpět do Stryn. V okolí je i letní lyžařské středisko Stryn sommerski.', 62.0186, 7.6569, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grotli.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grotli.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lom – sloupový kostel', 'Dřevěný sloupový kostel (stavkirke) z 12. století s dračími hlavami na střeše je dominantou horského městečka Lom. Městečko je zároveň bránou do Jotunheimenu a poslední větší zastávkou před průsmykem — natankujte a nakupte tady. Kostel stojí hned u hlavní silnice a prohlídka zabere půl hodiny.', 61.8390, 8.5669, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lom%20stavkirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lom%20stavkirke.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Bakeriet i Lom (Lom)', 'Slavná pekárna špičkového norského kuchaře Mortena Schakendy, kvůli které se v Lomu zastavuje celé Norsko. Skořicoví šneci, čerstvý chleba z kamenné pece a výborná káva — ideální motorkářská snídaně před výjezdem na průsmyk. Podnik má vynikající hodnocení a v sezóně tu bývá fronta, která ale stojí za to.', 61.8386, 8.5660, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bakeriet%20i%20Lom.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bakeriet%20i%20Lom.jpg"}'::text[], 1),
    (v_route, 'Sognefjellet – vrchol průsmyku', 'Nejvyšší bod silnice (1434 m) u moderní horské chaty Sognefjellshytta, obklopený ledovci Smørstabbreen a štíty Jotunheimenu. I uprostřed léta tu leží sníh a teploty padají k nule — přibalte teplé vrstvy. Chata nabízí polévku, kávu a úžasné panorama prosklenou stěnou.', 61.5646, 7.9938, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sognefjellet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sognefjellet.jpg"}'::text[], 2),
    (v_route, 'Turtagrø a štíty Hurrungane', 'Historický horolezecký hotel pod nejdivočejšími štíty Norska — žulové věže Hurrungane s vrcholem Store Skagastølstind (2405 m) jsou norský Matterhorn. Sjezd od hotelu dolů do údolí je kaskáda ostrých serpentin s výhledy, ze kterých se tají dech. Zastavte na terase hotelu na kávu s výhledem na stěny.', 61.5046, 7.8010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hurrungane.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hurrungane.jpg"}'::text[], 3),
    (v_route, 'Skjolden a Lustrafjord', 'Vesnička na samém konci Lustrafjordu — nejvnitřnějšího ramene Sognefjordu, nejdelšího a nejhlubšího fjordu světa. Po sjezdu z hor tu najednou jedete podél smaragdové hladiny mezi ovocnými sady. Ideální místo na oběd a odpočinek u vody.', 61.4839, 7.6040, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skjolden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skjolden.jpg"}'::text[], 4),
    (v_route, 'Urnes – sloupový kostel (UNESCO)', 'Nejstarší sloupový kostel Norska (kolem roku 1130) se slavnými vikingskými řezbami, zapsaný na seznamu UNESCO. Stojí nad Lustrafjordem a nejhezčí cesta k němu vede krátkým trajektem ze Solvornu — plavba přes fjord je zážitek navrch. Krásná tečka za celou trasou.', 61.2977, 7.3229, 'https://commons.wikimedia.org/wiki/Special:FilePath/Urnes%20stavkirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Urnes%20stavkirke.jpg"}'::text[], 5);
  insert into public.routes
