  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Steinsdalsfossen', 'Padesátimetrový vodopád u Norheimsundu, za jehož vodní clonou vede chodník — projdete se za vodopádem, aniž byste zmokli. Parkoviště je přímo u silnice, zastávka zabere čtvrt hodiny. Skvělé zahájení fjordové etapy.', 60.3739, 6.1120, 'https://commons.wikimedia.org/wiki/Special:FilePath/Steinsdalsfossen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steinsdalsfossen.jpg"}'::text[], 0),
    (v_route, 'Hardangerbrua', 'Jeden z nejdelších visutých mostů Evropy (1380 m) elegantně překlenuje Hardangerfjord mezi Bruravikem a Brimnes. Přejezd na motorce s fjordem sto metrů pod koly je malý svátek. Most nahradil trajekt a napojuje trasu přímo na Eidfjord.', 60.4790, 6.8330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hardangerbrua.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hardangerbrua.jpg"}'::text[], 1),
    (v_route, 'Eidfjord', 'Půvabná obec na konci stejnojmenného ramene fjordu, obklopená horskými stěnami — vstupní brána na náhorní plošinu Hardangervidda. Dobré místo na doplnění paliva a občerstvení před stoupáním soutěskou Måbødalen. V přístavu často kotví výletní lodě, dopoledne tu proto bývá živo.', 60.4671, 7.0716, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eidfjord.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eidfjord.jpg"}'::text[], 2),
    (v_route, 'Vøringsfossen', 'Nejslavnější vodopád Norska padá 182 metrů z hrany Hardangerviddy do soutěsky Måbødalen. Nové vyhlídkové lávky včetně schodového mostu přes rokli nabízejí pohledy přímo do hloubky. Samotná silnice Rv7 soutěskou nahoru je jízdní zážitek — serpentiny a tunely vytesané ve skále.', 60.4269, 7.2519, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B8ringsfossen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B8ringsfossen.jpg"}'::text[], 3),
    (v_route, 'Lofthus – ovocné sady', 'Srdce hardangerského ovocnářství: svahy nad Sørfjordenem pokrývají sady jabloní, třešní a švestek s ledovcem Folgefonna v pozadí. V květnu je to nejkrásnější kvetoucí krajina Norska, koncem léta u cesty koupíte ovoce a slavný místní cider. Silnice Rv13 podél fjordu je plynulá a výhledová.', 60.3330, 6.6620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lofthus%20i%20Hardanger.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lofthus%20i%20Hardanger.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Hotel Ullensvang (Lofthus)', 'Legendární rodinný hotel na břehu Sørfjordenu, kde tvořil i skladatel Edvard Grieg. Restaurace staví na místních surovinách — fjordový losos, jehněčí a ovoce ze sadů za domem — a má výborné hodnocení hostů. Ideální oběd s výhledem na fjord a ledovec Folgefonna.', 60.3236, 6.6580, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Ullensvang.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Ullensvang.jpg"}'::text[], 5),
    (v_route, 'Låtefossen', 'Dvojitý vodopád, jehož dvě ramena se spojují přímo nad silničním mostem — v plné síle stříká vodní tříšť až na projíždějící motorkáře. Jeden z nejfotografovanějších vodopádů země, parkoviště je hned vedle. Důstojná tečka za trasou kousek od Oddy.', 59.9487, 6.5817, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5tefossen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5tefossen.jpg"}'::text[], 6);
  insert into public.routes
