  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Restaurace: Fisketorget (Stavanger)', 'Vyhlášená rybí restaurace přímo na nábřeží stavangerského přístavu Vågen s vlastním rybím pultem. Denní úlovek, polévka z mořských plodů a čerstvé ústřice — hodnocení má výborné a po ránu tu seženete i lehčí snídani. Ideální start před vyjížďkou, kousek od kolonie bílých dřevěných domků Gamle Stavanger.', 58.9720, 5.7330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Stavanger.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Stavanger.jpg"}'::text[], 0),
    (v_route, 'Preikestolen', 'Kazatelna — dokonale rovná skalní plošina 604 metrů kolmo nad Lysefjordem a nejslavnější přírodní scéna Norska. Z parkoviště u Preikestolen fjellstue vede nahoru kamenná stezka, 8 km tam a zpět, počítejte 4 hodiny. Vyrazte brzy ráno, vyhnete se davům i odpolednímu vedru.', 58.9864, 6.1904, 'https://commons.wikimedia.org/wiki/Special:FilePath/Preikestolen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Preikestolen.jpg"}'::text[], 1),
    (v_route, 'Sand', 'Dřevěné městečko nad ústím lososí řeky Suldalslågen, správní centrum kraje Suldal. Bílé domky, malý přístav a lávka Høse bru přes řeku — příjemná zastávka na kávu v polovině cesty. V řece se dají v sezóně pozorovat lososi táhnoucí proti proudu.', 59.4890, 6.2536, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sand%20i%20Ryfylke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sand%20i%20Ryfylke.jpg"}'::text[], 2),
    (v_route, 'Svandalsfossen', 'Vodopád, který padá v několika stupních přímo k silnici před Saudou — z odpočívadla k němu vede 540 schodů až do vodní tříště. Při tání sněhu na jaře je jeho síla ohromující a sprcha zaručená. Parkování přímo u Rv13.', 59.6480, 6.3170, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svandalsfossen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svandalsfossen.jpg"}'::text[], 3),
    (v_route, 'Allmannajuvet', 'Areál staré zinkové štoly v hluboké soutěsce, přestavěný švýcarským architektem Peterem Zumthorem na minimalistické muzeum s kavárnou zavěšenou nad roklí. Kontrast syrové hornické historie a světové architektury je fascinující. Krátká odbočka ze silnice do Saudy, otevřeno v letní sezóně.', 59.6290, 6.3990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Allmannajuvet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Allmannajuvet.jpg"}'::text[], 4),
    (v_route, 'Sauda', 'Průmyslové městečko na konci Saudafjordu, obklopené horami — cíl trasy a dobré místo na nocleh. Odsud se dá pokračovat horskou silnicí přes Røldal na Hardanger, nebo se vrátit trajektem. V centru je několik kaváren a funkcionalistická dělnická čtvrť Åbøbyen.', 59.6506, 6.3540, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sauda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sauda.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bergsbotn – vyhlídková plošina', 'Čtyřicetimetrová dřevěná vyhlídková lávka vysunutá nad fjord Bergsfjorden s panoramatem štítů západní Senji. Silnice sem stoupá krásnými serpentinami z vnitrozemí ostrova. Zastávka přímo u cesty, výhled patří k nejlepším na trase.', 69.4430, 17.2120, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bergsbotn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bergsbotn.jpg"}'::text[], 0),
    (v_route, 'Hamn i Senja', 'Bývalá rybářská osada na skalnatém výběžku, dnes oblíbený resort s restaurací a molem mezi ostrůvky. Skvělé místo na oběd s výhledem na otevřené moře — kuchyně staví na čerstvých rybách a arktických surovinách. V okolí se dají pozorovat orli mořští.', 69.4664, 17.1746, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hamn%20i%20Senja.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hamn%20i%20Senja.jpg"}'::text[], 1),
    (v_route, 'Tungeneset a Okshornan', 'Architektonicky řešené odpočívadlo národní turistické cesty: sibiřským modřínem obložený chodník vede přes skaliska k výhledu na zubaté štíty Okshornan, přezdívané Ďáblovy zuby. Jedno z nejfotografovanějších míst severního Norska. Za vlnobití tu Atlantik buší do skal pár metrů od vás.', 69.5010, 17.3550, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tungeneset.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tungeneset.jpg"}'::text[], 2),
    (v_route, 'Ersfjordstranda', 'Bílá písečná pláž s tyrkysovou vodou zasazená mezi divoké štíty — arktický Karibik. U pláže je zlatě obložené servisní zázemí, další z architektonických perel turistické cesty. Otužilci se můžou vykoupat, ostatní aspoň vyfotí motorku na pozadí, které nikdo neuvěří.', 69.5160, 17.4210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ersfjordstranda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ersfjordstranda.jpg"}'::text[], 3),
    (v_route, 'Fjordgård a hora Segla', 'Rybářská vesnice pod dokonale tvarovaným štítem Segla (639 m), který se jako plachta zvedá kolmo z moře. Túra na vrchol (asi 3 hodiny tam a zpět) patří k nejslavnějším v severním Norsku, výhled z hrany je závratný. Cesta do vesnice vede tunely skrz horské hřebeny.', 69.5486, 17.6489, 'https://commons.wikimedia.org/wiki/Special:FilePath/Segla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Segla.jpg"}'::text[], 4),
    (v_route, 'Husøy', 'Celá vesnice na jednom malém ostrůvku uprostřed fjordu Øyfjorden, spojená s Senjou jen náspem — jedno z nejmalebnějších rybářských sídel Norska. Domky tu stojí doslova jeden na druhém a život se točí kolem přístavu. Krátká odbočka, která stojí za to.', 69.6320, 17.6560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hus%C3%B8y%20i%20Senja.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hus%C3%B8y%20i%20Senja.jpg"}'::text[], 5);
