  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Torghatten', 'Žulová hora s 160 metrů dlouhou dírou skrz celý masiv — podle legendy ji prostřelil trollí šíp. K otvoru vede z parkoviště pohodová stezka (asi 20 minut) a průhled skrz horu na moře je surrealistický zážitek. Symbol jižního Helgelandu kousek od Brønnøysundu.', 65.3970, 12.0930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torghatten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torghatten.jpg"}'::text[], 0),
    (v_route, 'De syv søstre – Sedm sester', 'Hřeben sedmi štítů nad Sandnessjøenem, který podle pověsti tvoří zkamenělé trollí dcery. Silnice vede přímo pod tisícimetrovými vrcholy a panorama vás doprovází desítky kilometrů. Sandnessjøen je zároveň dobrá zastávka na tankování a nocleh.', 66.0217, 12.6316, 'https://commons.wikimedia.org/wiki/Special:FilePath/De%20syv%20s%C3%B8stre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/De%20syv%20s%C3%B8stre.jpg"}'::text[], 1),
    (v_route, 'Svartisen – ledovec Engabreen', 'Druhý největší ledovec Norska stéká splazem Engabreen téměř až k hladině Holandsfjordenu — modrý led je vidět přímo ze silnice Fv17. Z přístaviště Holand jezdí v létě lodička přes fjord, odkud je to k čelu ledovce hodinová procházka. Cestou sem navíc trajekt Kilboghamn–Jektvik protíná polární kruh.', 66.6790, 13.8500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Engabreen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Engabreen.jpg"}'::text[], 2),
    (v_route, 'Saltstraumen', 'Nejsilnější slapový proud na světě: každých šest hodin se úžinou prožene 400 milionů kubíků vody a roztočí obří víry. Nejlepší pohled je z mostu nad úžinou; časy nejsilnějšího proudu najdete v přílivové tabulce. Ráj rybářů — tresky tu loví přímo ze břehu.', 67.2340, 14.6190, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saltstraumen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Saltstraumen.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Bryggerikaia (Bodø)', 'Oblíbená restaurace na nábřeží v Bodø s vlastním minipivovarem a výhledem na přístav. Na talíři severská klasika — treska skrei, rybí polévka, sobí maso — a hodnocení patří k nejlepším ve městě. Zasloužená oslava dojezdu na konci Kystriksveien.', 67.2830, 14.3780, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bod%C3%B8.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bod%C3%B8.jpg"}'::text[], 4);
