  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Beitostølen', 'Horské středisko na jižním okraji Jotunheimenu, poslední větší zastávka před náhorní plošinou. Kavárny, pumpa a obchody pohromadě — doplňte zásoby a teplé vrstvy. Odsud silnice stoupá do otevřené tundry.', 61.2496, 8.9070, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beitost%C3%B8len.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beitost%C3%B8len.jpg"}'::text[], 0),
    (v_route, 'Valdresflye – náhorní plošina', 'Nejvyšší bod silnice (1389 m) uprostřed nekonečné vysokohorské tundry s výhledem na ledovcové štíty Jotunheimenu. U vyhlídky Rjupa stojí originální betonové odpočívadlo národní turistické cesty. Mezi sněhovými poli se tu pasou sobi a ovce — jeďte s okem na krajnici.', 61.4370, 8.8130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Valdresflya.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Valdresflya.jpg"}'::text[], 1),
    (v_route, 'Jezero Gjende a hřeben Besseggen', 'Smaragdově zelené ledovcové jezero, nad kterým se táhne Besseggen — nejslavnější hřebenová túra Norska, kterou proslavil už Ibsenův Peer Gynt. Od chaty Gjendesheim vyplouvají lodě přes jezero do Memurubu, odkud se hřeben přechází zpět (celý den). I krátká zastávka u jezera stojí za to.', 61.4952, 8.8069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Besseggen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Besseggen.jpg"}'::text[], 2),
    (v_route, 'Ridderspranget', 'Rytířský skok — sevřená skalní soutěska, kterou se divoká řeka Sjoa prodírá jen pár metrů širokou průrvou. Podle pověsti ji přeskočil rytíř prchající s unesenou nevěstou. Od parkoviště krátká procházka lesem, síla vody je slyšet už z dálky.', 61.5232, 9.0448, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ridderspranget.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ridderspranget.jpg"}'::text[], 3),
    (v_route, 'Vågåmo', 'Půvabné městečko v údolí Otty se středověkým kostelem z roku 1130, roubenými domy a příjemným centrem. Cíl trasy a křižovatka dalších cest — odsud je kousek do Lomu a na Sognefjellet. Ideální místo na odpolední kávu po sjezdu z hor.', 61.8754, 9.0967, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A5g%C3%A5%20kyrkje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A5g%C3%A5%20kyrkje.jpg"}'::text[], 4);
