  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Flåm', 'Turistická vesnice na konci Aurlandsfjordu, výchozí bod slavné horské železnice Flåmsbana a náš start. Přístav, muzeum železnice a spousta kaváren — dopoledne tu bývá rušno kvůli výletním lodím. Natankujte, nahoře na plošině žádná pumpa není.', 60.8630, 7.1130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5msbana.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5msbana.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Ægir BryggeriPub (Flåm)', 'Proslulý minipivovar v budově inspirované vikingskou architekturou přímo u flåmského přístavu. Vikinská ochutnávková prkna, uzené sobí maso a pivo oceňované po celém Norsku; hodnocení hostů je výborné. Skvělý oběd před výjezdem na Sněžnou cestu — s mírou, hory teprve přijdou.', 60.8622, 7.1136, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5m.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5m.jpg"}'::text[], 1),
    (v_route, 'Stegastein', 'Ikonická dřevěná vyhlídka vybíhající 30 metrů do prostoru 650 metrů nad Aurlandsfjordem — lávka se na konci stáčí dolů a končí jen skleněným zábradlím nad propastí. Jedno z nejfotografovanějších míst norských fjordů. Serpentiny z Aurlandu nahoru jsou samy o sobě skvělá jízda.', 60.9047, 7.2110, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stegastein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stegastein.jpg"}'::text[], 2),
    (v_route, 'Aurlandsfjellet – Snøvegen', 'Vrcholová část Sněžné cesty: holé kamenné plató ve 1300 metrech, kde i uprostřed léta projíždíte mezi sněhovými poli a tyrkysovými jezírky. Krajina působí měsíčně a počasí se mění po minutách. Jednopruhová silnice s výhybnami — jeďte předvídavě a užívejte si ticho.', 60.9600, 7.3600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aurlandsfjellet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aurlandsfjellet.jpg"}'::text[], 3),
    (v_route, 'Lærdalsøyri', 'Historické městečko na břehu Sognefjordu se 160 chráněnými dřevěnými domy z 18. a 19. století. Úzké uličky starého jádra jsou jako kulisy z filmu — projděte se a dejte si kávu. Odsud vede údolí Lærdal, proslulé lososí řekou, vzhůru k Borgundu.', 61.0996, 7.4810, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A6rdals%C3%B8yri.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A6rdals%C3%B8yri.jpg"}'::text[], 4),
    (v_route, 'Borgund – sloupový kostel', 'Nejzachovalejší sloupový kostel Norska z roku 1180 — celý ze dřeva, s dračími hlavami na hřebenech střech a runovými nápisy na portálech. Vedle stojí návštěvnické centrum s expozicí o stavbě stavkirke. Důstojné zakončení trasy; zpět do Flåmu se dá vrátit tunelem za 40 minut.', 61.0470, 7.8122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Borgund%20stavkirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Borgund%20stavkirke.jpg"}'::text[], 5);
