  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Svolvær', 'Hlavní město Lofot s přístavem pod skalní věží Svolværgeita, na kterou horolezci skáčou mezi jejími „rohy". Dobrá základna s hotely, půjčovnami a trajektem na pevninu. Odsud startuje celá lofotská jízda na jihozápad.', 68.2343, 14.5681, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svolv%C3%A6r.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svolv%C3%A6r.jpg"}'::text[], 0),
    (v_route, 'Henningsvær', 'Rybářská vesnice roztroušená po ostrůvcích na konci úzké silničky pod stěnou hory Vågakallen — přezdívá se jí Benátky severu. Proslavil ji fotbalový plácek na skalním ostrůvku, jeden z nejfotografovanějších na světě. Galerie, kavárny a přístav plný člunů lákají ke korzování.', 68.1550, 14.2038, 'https://commons.wikimedia.org/wiki/Special:FilePath/Henningsv%C3%A6r.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Henningsv%C3%A6r.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Fiskekrogen (Henningsvær)', 'Legendární rybí restaurace přímo na molu henningsværského přístavu, oblíbená i norskou královskou rodinou. Vyhlášená rybí polévka, treska skrei a mořské plody z denního úlovku; hodnocení dlouhodobě výborné. Ideální oběd uprostřed lofotské etapy.', 68.1556, 14.2050, 'https://commons.wikimedia.org/wiki/Special:FilePath/Henningsv%C3%A6r%20havn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Henningsv%C3%A6r%20havn.jpg"}'::text[], 2),
    (v_route, 'Hauklandstranda', 'Bílá písečná pláž s průzračnou tyrkysovou vodou, pravidelně volená nejkrásnější plaží Norska. Kolem vede úzká pobřežní silnička do sousední zátoky Uttakleiv — krátký, ale nádherný vyhlídkový úsek. Zaparkujte, projděte se po písku a nechte si vyrazit dech kontrastem hor a moře.', 68.2010, 13.5220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hauklandstranda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hauklandstranda.jpg"}'::text[], 3),
    (v_route, 'Nusfjord', 'Jedna z nejstarších a nejzachovalejších rybářských osad Norska, schovaná v úzké zátoce na konci odbočky z E10. Červené rorbuer na kůlech, stará pekárna a sušáky na tresky — časová kapsle z 19. století. Za vjezd do vesnice se v sezóně platí drobné vstupné, ale stojí za to.', 68.0340, 13.3510, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusfjord.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nusfjord.jpg"}'::text[], 4),
    (v_route, 'Reine', 'Vesnice na skalnatém poloostrově uprostřed Reinefjordu, obklopená věncem špičatých štítů — pravděpodobně nejfotografovanější scenérie Norska. Cestou sem přejedete fotogenické mosty přes Hamnøy, kde červené chaty stojí přímo nad příbojem. Kdo má čas, vyběhne na vyhlídku Reinebringen (velmi strmé schody).', 67.9320, 13.0880, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reine.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Reine.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hamn%C3%B8y.jpg"}'::text[], 5),
    (v_route, 'Å i Lofoten', 'Vesnice s nejkratším jménem na světě a doslovný konec silnice E10 — dál už je jen moře. Muzeum sušených tresek, stará pekárna s vyhlášenými skořicovými šneky a přístav s rorbuer. Symbolické místo na závěrečnou fotku: dojeli jste na konec Lofot.', 67.8790, 12.9770, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%85%20i%20Lofoten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%85%20i%20Lofoten.jpg"}'::text[], 6);
