-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — NORSKO (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Lysevegen a Kjerag – serpentiny nad Lysefjordem
  delete from public.routes where name = 'Lysevegen a Kjerag – serpentiny nad Lysefjordem' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Lysevegen a Kjerag – serpentiny nad Lysefjordem', 'Jedna z nejdivočejších silnic Norska: horská Lysevegen se z náhorní plošiny Sirdalu vrhá 27 serpentinami o 900 výškových metrů dolů do Lysebotnu na samém konci Lysefjordu. Z údolí Sirdal stoupáte holou skandinávskou tundrou mezi jezery a sněhovými poli až k vyhlídce Øygardstøl, odkud startuje slavná túra na skalní kouli Kjeragbolten. Pak přijde ten nejlepší kus: úzké, technické vlásenky s jedním jednosměrným tunelem vytesaným do skály, kde budete pracovat s předním kolem doslova metr po metru. Z Lysebotnu se dá pokračovat trajektem celým Lysefjordem — plavba pod kolmými tisícimetrovými stěnami je zážitek sama o sobě. Silnice je otevřená zhruba od konce května do října; i v létě počítejte s chladem, mlhou a zbytky sněhu nahoře. Pozor na úzký profil, protijedoucí karavany a štěrk v zatáčkách — jde o náročnou, ale nezapomenutelnou jízdu.', 'poi', 95, 150, 'hard',
     '[{"lat": 58.6644, "lng": 6.7147, "label": "Start: Tonstad (Sirdal)"}, {"lat": 58.9243, "lng": 6.8577, "label": "Tjørhom"}, {"lat": 58.9884, "lng": 6.8548, "label": "Ådneram"}, {"lat": 59.0339, "lng": 6.6496, "label": "Øygardstøl"}, {"lat": 59.0553, "lng": 6.6432, "label": "Cíl: Lysebotn"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=58.6644,6.7147&destination=59.0553,6.6432&travelmode=driving&waypoints=58.9243,6.8577%7C58.9884,6.8548%7C59.0339,6.6496', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kjeragbolten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%98ygardst%C3%B8l.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kjeragbolten.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lysevegen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lysebotn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lysefjorden.jpg"}'::text[], '{"Øygardstøl – Orlí hnízdo","Kjeragbolten","Lysevegen – 27 serpentin","Lysebotn","Lysefjord – plavba trajektem"}'::text[], '{"NO"}'::text[], false, 4610, 'approved');

  -- Gamle Strynefjellsvegen – historická cesta přes hory
  delete from public.routes where name = 'Gamle Strynefjellsvegen – historická cesta přes hory' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Gamle Strynefjellsvegen – historická cesta přes hory', 'Stará silnice přes Strynefjellet z roku 1894 je národní turistická cesta a jedna z nejatmosféričtějších jízd Norska: úzká cesta lemovaná ručně skládanými kamennými patníky se vine mezi sněhovými poli, vodopády a ledovcovými jezery. Startujete ve Stryn u smaragdově zelených jezer, vystoupáte serpentinami kolem hřmícího vodopádu Videfossen k horskému hotelu Videseter a pak se po historické Rv258 přehoupnete přes náhorní plošinu do Grotli. Část cesty má zpevněný šotolinový povrch, který je ale udržovaný a na motorce v pohodě zvladatelný — jen zvolněte a užívejte si to. Silnice je otevřená zhruba od června do září a i v červenci tu můžete jet mezi několikametrovými sněhovými mantinely. Pozor na měnlivé horské počasí, ovce na cestě a protijedoucí auta v úzkých místech.', 'poi', 80, 120, 'medium',
     '[{"lat": 61.9046, "lng": 6.7114, "label": "Start: Stryn"}, {"lat": 61.8380, "lng": 6.8480, "label": "Loen"}, {"lat": 61.9727, "lng": 7.2320, "label": "Videseter"}, {"lat": 61.9950, "lng": 7.3900, "label": "Gamle Strynefjellsvegen"}, {"lat": 62.0186, "lng": 7.6569, "label": "Cíl: Grotli"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=61.9046,6.7114&destination=62.0186,7.6569&travelmode=driving&waypoints=61.8380,6.8480%7C61.9727,7.2320%7C61.9950,7.3900', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Strynefjellsvegen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stryn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lovatnet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Videfossen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Videseter.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Strynefjellsvegen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grotli.jpg"}'::text[], '{"Stryn","Loen a jezero Lovatnet","Videfossen","Videseter","Gamle Strynefjellsvegen","Grotli"}'::text[], '{"NO"}'::text[], false, 4620, 'approved');

  -- Sognefjellet – střecha Norska (Fv55)
  delete from public.routes where name = 'Sognefjellet – střecha Norska (Fv55)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Sognefjellet – střecha Norska (Fv55)', 'Sognefjellsvegen (Fv55) je nejvýše položený horský průsmyk severní Evropy — 1434 metrů — a vede přímo mezi ledovci národního parku Jotunheimen. Z Lomu se slavným sloupovým kostelem stoupáte údolím Bøverdalen pod nejvyšší horu Norska Galdhøpiggen, pak následuje otevřená vysokohorská plošina se sněhem i v červenci a dramatický sjezd serpentinami kolem Turtagrø pod žulové štíty Hurrungane. Dole vás čeká pohlednicový Skjolden na konci nejdelšího fjordu světa a jako třešnička trajekt k nejstaršímu sloupovému kostelu Norska v Urnes (UNESCO). Asfalt je kvalitní, zatáčky plynulé a provoz mimo špičku překvapivě mírný. Silnice je celoročně sjízdná jen omezeně — ideální okno je červen až září. Nahoře počítejte s chladem kolem 5 °C, větrem a rychlými změnami počasí.', 'poi', 135, 210, 'medium',
     '[{"lat": 61.8390, "lng": 8.5669, "label": "Start: Lom"}, {"lat": 61.5646, "lng": 7.9938, "label": "Sognefjellshytta"}, {"lat": 61.5046, "lng": 7.8010, "label": "Turtagrø"}, {"lat": 61.4839, "lng": 7.6040, "label": "Skjolden"}, {"lat": 61.2977, "lng": 7.3229, "label": "Cíl: Urnes"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=61.8390,8.5669&destination=61.2977,7.3229&travelmode=driving&waypoints=61.5646,7.9938%7C61.5046,7.8010%7C61.4839,7.6040', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lom%20stavkirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lom%20stavkirke.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bakeriet%20i%20Lom.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sognefjellet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hurrungane.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skjolden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Urnes%20stavkirke.jpg"}'::text[], '{"Lom – sloupový kostel","Restaurace: Bakeriet i Lom (Lom)","Sognefjellet – vrchol průsmyku","Turtagrø a štíty Hurrungane","Skjolden a Lustrafjord","Urnes – sloupový kostel (UNESCO)"}'::text[], '{"NO"}'::text[], false, 4630, 'approved');

  -- Hardanger – vodopády a ovocné sady
  delete from public.routes where name = 'Hardanger – vodopády a ovocné sady' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Hardanger – vodopády a ovocné sady', 'Hardangerfjord je ovocný sad Norska — a jeho břehy lemuje jedna z nejpříjemnějších fjordových silnic vůbec. Trasa začíná u vodopádu Steinsdalsfossen, za kterým se dá projít suchou nohou, pokračuje po Fv7 podél fjordu přes elegantní visutý most Hardangerbrua a soutěskou Måbødalen vystoupá k Vøringsfossen, nejslavnějšímu vodopádu země se 182 metry volného pádu. Zpáteční rameno vede po Rv13 podél Sørfjordenu skrz ovocné sady v Lofthus — v květnu tu kvetou statisíce jabloní, na konci léta koupíte u cesty čerstvé třešně a cider. Finále obstará dvojitý vodopád Låtefossen u Oddy, který stříká přímo na silnici. Jízdně jde o pohodovou, plynulou trasu s kvalitním asfaltem; ideální sezóna je květen až září. Pozor na turistický provoz u vyhlídek a mokrou vozovku u vodopádů.', 'poi', 165, 240, 'medium',
     '[{"lat": 60.3720, "lng": 6.1470, "label": "Start: Norheimsund"}, {"lat": 60.3739, "lng": 6.1120, "label": "Steinsdalsfossen"}, {"lat": 60.4790, "lng": 6.8330, "label": "Hardangerbrua"}, {"lat": 60.4671, "lng": 7.0716, "label": "Eidfjord"}, {"lat": 60.4269, "lng": 7.2519, "label": "Vøringsfossen"}, {"lat": 60.3330, "lng": 6.6620, "label": "Lofthus"}, {"lat": 59.9487, "lng": 6.5817, "label": "Cíl: Låtefossen"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.3720,6.1470&destination=59.9487,6.5817&travelmode=driving&waypoints=60.3739,6.1120%7C60.4790,6.8330%7C60.4671,7.0716%7C60.4269,7.2519%7C60.3330,6.6620', 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B8ringsfossen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steinsdalsfossen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hardangerbrua.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Eidfjord.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B8ringsfossen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lofthus%20i%20Hardanger.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Ullensvang.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5tefossen.jpg"}'::text[], '{"Steinsdalsfossen","Hardangerbrua","Eidfjord","Vøringsfossen","Lofthus – ovocné sady","Restaurace: Hotel Ullensvang (Lofthus)","Låtefossen"}'::text[], '{"NO"}'::text[], false, 4640, 'approved');

  -- Ryfylke – Preikestolen a cesta vodopádů do Saudy
  delete from public.routes where name = 'Ryfylke – Preikestolen a cesta vodopádů do Saudy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Ryfylke – Preikestolen a cesta vodopádů do Saudy', 'Národní turistická cesta Ryfylke (Rv13) vede ze Stavangeru fjordovou krajinou na sever přes trajekty, tunely a vodopády až do horského městečka Sauda. Po ránu stihnete slavnou skalní plošinu Preikestolen — kolmý sráz 604 metrů nad Lysefjordem (túra 8 km tam a zpět) — a pak se ponoříte do klidného Ryfylke: trajekt přes fjord u Hjelmelandu, dřevěné městečko Sand nad řekou Suldalslågen a vodopád Svandalsfossen, kterému vyjedete po schodech přímo do vodní tříště. Před Saudou stojí architektonický skvost Allmannajuvet — stará zinková štola s pavilonem Petera Zumthora zavěšeným v soutěsce. Silnice je kombinace plynulých fjordových pasáží a užších technických úseků, provoz je mimo Preikestolen minimální. Nejlepší období je květen až září; počítejte s časem na trajekt a s mokrým asfaltem u vodopádů.', 'poi', 175, 300, 'medium',
     '[{"lat": 58.9700, "lng": 5.7331, "label": "Start: Stavanger"}, {"lat": 58.9926, "lng": 6.1420, "label": "Preikestolen – parkoviště"}, {"lat": 59.2370, "lng": 6.1810, "label": "Hjelmeland – trajekt"}, {"lat": 59.4890, "lng": 6.2536, "label": "Sand"}, {"lat": 59.6480, "lng": 6.3170, "label": "Svandalsfossen"}, {"lat": 59.6506, "lng": 6.3540, "label": "Cíl: Sauda"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=58.9700,5.7331&destination=59.6506,6.3540&travelmode=driving&waypoints=58.9926,6.1420%7C59.2370,6.1810%7C59.4890,6.2536%7C59.6480,6.3170', 'https://commons.wikimedia.org/wiki/Special:FilePath/Preikestolen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gamle%20Stavanger.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Preikestolen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sand%20i%20Ryfylke.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Svandalsfossen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Allmannajuvet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sauda.jpg"}'::text[], '{"Restaurace: Fisketorget (Stavanger)","Preikestolen","Sand","Svandalsfossen","Allmannajuvet","Sauda"}'::text[], '{"NO"}'::text[], false, 4650, 'approved');

  -- Senja – arktický ostrov štítů a pláží
  delete from public.routes where name = 'Senja – arktický ostrov štítů a pláží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Senja – arktický ostrov štítů a pláží', 'Senja je druhý největší ostrov Norska a mezi motorkáři platí za „Lofoty bez davů": národní turistická cesta Fv862 po jeho vnějším pobřeží střídá tunely, mosty a serpentiny mezi zubatými štíty padajícími rovnou do Atlantiku. Z Finnsnes se dostanete na západní pobřeží k vyhlídkové plošině Bergsbotn a resortu Hamn i Senja, pak následuje ikonické odpočívadlo Tungeneset s výhledem na zuby Okshornan a bílá pláž Ersfjordstranda s tyrkysovou vodou jako z Karibiku — jen o 40 stupňů severněji. Finále patří rybářské vesnici Fjordgård pod slavnou horou Segla a trajektu z Botnhamnu směr Tromsø. Za polárním kruhem se v létě jezdí pod půlnočním sluncem, které celou trasu barví do zlata. Ideální okno je červen až srpen; počítejte s úzkými úseky, ovcemi na silnici a rychlými změnami počasí od moře.', 'poi', 115, 180, 'medium',
     '[{"lat": 69.2295, "lng": 17.9811, "label": "Start: Finnsnes"}, {"lat": 69.4430, "lng": 17.2120, "label": "Bergsbotn"}, {"lat": 69.4664, "lng": 17.1746, "label": "Hamn i Senja"}, {"lat": 69.5010, "lng": 17.3550, "label": "Tungeneset"}, {"lat": 69.5486, "lng": 17.6489, "label": "Fjordgård"}, {"lat": 69.6280, "lng": 17.8340, "label": "Cíl: Botnhamn (trajekt)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=69.2295,17.9811&destination=69.6280,17.8340&travelmode=driving&waypoints=69.4430,17.2120%7C69.4664,17.1746%7C69.5010,17.3550%7C69.5486,17.6489', 'https://commons.wikimedia.org/wiki/Special:FilePath/Segla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bergsbotn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hamn%20i%20Senja.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tungeneset.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ersfjordstranda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Segla.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hus%C3%B8y%20i%20Senja.jpg"}'::text[], '{"Bergsbotn – vyhlídková plošina","Hamn i Senja","Tungeneset a Okshornan","Ersfjordstranda","Fjordgård a hora Segla","Husøy"}'::text[], '{"NO"}'::text[], false, 4660, 'approved');

  -- Helgeland – pobřežní cesta Fv17 za polární kruh
  delete from public.routes where name = 'Helgeland – pobřežní cesta Fv17 za polární kruh' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Helgeland – pobřežní cesta Fv17 za polární kruh', 'Kystriksveien (Fv17) z Brønnøysundu do Bodø je považována za jednu z nejkrásnějších pobřežních silnic světa: 440 kilometrů mezi tisíci ostrůvky, horskými hřebeny a ledovci, proložených šesti trajekty — právě plavby mezi ostrovy dělají z cesty expedici. Začíná se u hory Torghatten s dírou skrz naskrz, pokračuje pod hřebenem Sedmi sester u Sandnessjøenu a trajektem přes polární kruh k ledovci Svartisen, jehož splaz Engabreen stéká téměř k moři. Velkolepým finále je Saltstraumen — nejsilnější slapový proud světa — a přístavní Bodø. Silnice je kvalitní a provoz řídký, jde ale o dlouhou etapu: rozdělte si ji na dva až tři dny a trajekty v hlavní sezóně nepodceňujte, tvoří se u nich fronty. Nejlepší období je červen až srpen, kdy se jezdí pod půlnočním sluncem. Počítejte s větrem od moře a proměnlivým počasím.', 'poi', 440, 780, 'medium',
     '[{"lat": 65.4740, "lng": 12.2120, "label": "Start: Brønnøysund"}, {"lat": 65.3970, "lng": 12.0930, "label": "Torghatten"}, {"lat": 66.0217, "lng": 12.6316, "label": "Sandnessjøen"}, {"lat": 66.6790, "lng": 13.8500, "label": "Svartisen – Engabreen"}, {"lat": 67.2340, "lng": 14.6190, "label": "Saltstraumen"}, {"lat": 67.2804, "lng": 14.4049, "label": "Cíl: Bodø"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=65.4740,12.2120&destination=67.2804,14.4049&travelmode=driving&waypoints=65.3970,12.0930%7C66.0217,12.6316%7C66.6790,13.8500%7C67.2340,14.6190', 'https://commons.wikimedia.org/wiki/Special:FilePath/Torghatten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torghatten.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/De%20syv%20s%C3%B8stre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Engabreen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Saltstraumen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bod%C3%B8.jpg"}'::text[], '{"Torghatten","De syv søstre – Sedm sester","Svartisen – ledovec Engabreen","Saltstraumen","Restaurace: Bryggerikaia (Bodø)"}'::text[], '{"NO"}'::text[], false, 4670, 'approved');

  -- Valdresflye – náhorní cestou do Jotunheimenu
  delete from public.routes where name = 'Valdresflye – náhorní cestou do Jotunheimenu' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Valdresflye – náhorní cestou do Jotunheimenu', 'Národní turistická cesta Fv51 přes náhorní plošinu Valdresflye je nejpohodovější způsob, jak si na motorce vychutnat velehory Jotunheimenu: široká, plynulá silnice stoupá z Fagernes přes horské středisko Beitostølen až do 1389 metrů, kde se otevře panorama ledovcových štítů, stád ovcí a sobů a nekonečné tundry. Sjezd vás přivede k jezeru Gjende, nad kterým se táhne slavný hřeben Besseggen, a dál údolím řeky Sjoa kolem skalní soutěsky Ridderspranget do Vågåmo se středověkým kostelem. Jízdně jde o snadnou trasu s výborným asfaltem a mírným provozem — ideální i pro méně zkušené jezdce, kteří chtějí velehorskou scenérii bez vlásenek. Nejlepší období je červen až září; nahoře bývá chladno a větrno i v létě. Brzy ráno a večer pozor na volně se pasoucí ovce na silnici.', 'poi', 125, 180, 'easy',
     '[{"lat": 60.9860, "lng": 9.2320, "label": "Start: Fagernes"}, {"lat": 61.2496, "lng": 8.9070, "label": "Beitostølen"}, {"lat": 61.4370, "lng": 8.8130, "label": "Valdresflye"}, {"lat": 61.4952, "lng": 8.8069, "label": "Gjendesheim"}, {"lat": 61.5232, "lng": 9.0448, "label": "Ridderspranget"}, {"lat": 61.8754, "lng": 9.0967, "label": "Cíl: Vågåmo"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.9860,9.2320&destination=61.8754,9.0967&travelmode=driving&waypoints=61.2496,8.9070%7C61.4370,8.8130%7C61.4952,8.8069%7C61.5232,9.0448', 'https://commons.wikimedia.org/wiki/Special:FilePath/Valdresflya.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beitost%C3%B8len.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Valdresflya.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Besseggen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ridderspranget.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A5g%C3%A5%20kyrkje.jpg"}'::text[], '{"Beitostølen","Valdresflye – náhorní plošina","Jezero Gjende a hřeben Besseggen","Ridderspranget","Vågåmo"}'::text[], '{"NO"}'::text[], false, 4680, 'approved');

  -- Aurlandsfjellet – Snøvegen a vyhlídka Stegastein
  delete from public.routes where name = 'Aurlandsfjellet – Snøvegen a vyhlídka Stegastein' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Aurlandsfjellet – Snøvegen a vyhlídka Stegastein', 'Aurlandsfjellet, přezdívaný Snøvegen (Sněžná cesta), je horská alternativa k nejdelšímu silničnímu tunelu světa: místo 24,5 km tmy vás čeká 47 km úzké silnice přes holé kamenné plató, kde sněhové bariéry lemují cestu i v červenci. Start je ve Flåmu na konci Aurlandsfjordu, první vrchol přijde rychle — dřevěná vyhlídka Stegastein vybíhající 30 metrů do prázdna 650 metrů nad fjordem. Pak následuje měsíční krajina vrcholové plošiny a dlouhý sjezd do Lærdalu s uličkami starých dřevěných domů. Tečkou je Borgund, nejzachovalejší sloupový kostel Norska z roku 1180. Silnice je z velké části jednopruhová s výhybnami, takže jde spíš o pomalou vychutnávací jízdu než o stíhačku. Otevřeno zhruba od června do října podle sněhu; nahoře počítejte s mlhou, větrem a teplotami pod 10 °C.', 'poi', 90, 150, 'medium',
     '[{"lat": 60.8630, "lng": 7.1130, "label": "Start: Flåm"}, {"lat": 60.9047, "lng": 7.2110, "label": "Stegastein"}, {"lat": 60.9600, "lng": 7.3600, "label": "Aurlandsfjellet – plató"}, {"lat": 61.0996, "lng": 7.4810, "label": "Lærdalsøyri"}, {"lat": 61.0470, "lng": 7.8122, "label": "Cíl: Borgund stavkirke"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.8630,7.1130&destination=61.0470,7.8122&travelmode=driving&waypoints=60.9047,7.2110%7C60.9600,7.3600%7C61.0996,7.4810', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stegastein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5msbana.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5m.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stegastein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aurlandsfjellet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A6rdals%C3%B8yri.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Borgund%20stavkirke.jpg"}'::text[], '{"Flåm","Restaurace: Ægir BryggeriPub (Flåm)","Stegastein","Aurlandsfjellet – Snøvegen","Lærdalsøyri","Borgund – sloupový kostel"}'::text[], '{"NO"}'::text[], false, 4690, 'approved');

  -- Lofoty – E10 mezi štíty a plážemi
  delete from public.routes where name = 'Lofoty – E10 mezi štíty a plážemi' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Lofoty – E10 mezi štíty a plážemi', 'Souostroví Lofoty je koncentrát toho nejlepšího z Norska na sto třiceti kilometrech: silnice E10 a její odbočky kličkují mezi žulovými štíty rostoucími přímo z moře, přes mosty spojující ostrovy a kolem rybářských vesnic s červenými chatami rorbuer na kůlech. Ze Svolværu zamíříte do galerijního Henningsvær s přístavem plným člunů, pak na bílou pláž Haukland a do časové kapsle Nusfjordu. Velkolepé finále obstará Reine s nejfotografovanějším panoramatem země a vesnička s nejkratším jménem na světě — Å, kde silnice doslova končí. V červnu a červenci se jezdí pod půlnočním sluncem, všude voní sušená treska a moře má barvu Karibiku. Jízdně jde o nenáročnou trasu; počítejte ale s letním provozem karavanů, bočním větrem na mostech a úzkými odbočkami k plážím.', 'poi', 130, 210, 'easy',
     '[{"lat": 68.2343, "lng": 14.5681, "label": "Start: Svolvær"}, {"lat": 68.1550, "lng": 14.2038, "label": "Henningsvær"}, {"lat": 68.2010, "lng": 13.5220, "label": "Hauklandstranda"}, {"lat": 68.0340, "lng": 13.3510, "label": "Nusfjord"}, {"lat": 67.9320, "lng": 13.0880, "label": "Reine"}, {"lat": 67.8790, "lng": 12.9770, "label": "Cíl: Å i Lofoten"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=68.2343,14.5681&destination=67.8790,12.9770&travelmode=driving&waypoints=68.1550,14.2038%7C68.2010,13.5220%7C68.0340,13.3510%7C67.9320,13.0880', 'https://commons.wikimedia.org/wiki/Special:FilePath/Reine.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svolv%C3%A6r.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Henningsv%C3%A6r.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Henningsv%C3%A6r%20havn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hauklandstranda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nusfjord.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Reine.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C3%85%20i%20Lofoten.jpg"}'::text[], '{"Svolvær","Henningsvær","Restaurace: Fiskekrogen (Henningsvær)","Hauklandstranda","Nusfjord","Reine","Å i Lofoten"}'::text[], '{"NO"}'::text[], false, 4700, 'approved');

